// src/payments/sync/payment-sync.service.ts
init_pool();
init_wallet_repository();
init_logger();
var paymentSyncService2 = {
  async syncQRStatus(qrId) {
    const qr = await qrRepository.getByQrId(qrId);
    if (!qr || qr.status === "used" || qr.status === "cancelled")
      return { changed: false };
    const cred = await resolveCredentials(qr.banecoCredentialId, qr.banecoEnvironment || "prod");
    try {
      const adapter = new BanecoAdapter(cred.api_base_url, cred.encryption_key);
      const token = await adapter.getToken(cred.username, cred.password);
      const status2 = await adapter.getQrStatus(token, qrId);
      if (status2.status === "PAID" || status2.status === "COMPLETED") {
        const claim = await query(`UPDATE qr_codes SET status = 'used', updated_at = CURRENT_TIMESTAMP
           WHERE qr_id = $1 AND status = 'active'`, [qrId]);
        if (claim.rowCount === 0) {
          await query(`
            INSERT INTO payment_sync_status (qr_id, last_checked, check_count, success, final_status)
            VALUES ($1, CURRENT_TIMESTAMP, 1, true, 'completed')
            ON CONFLICT (qr_id) DO UPDATE SET
              last_checked = CURRENT_TIMESTAMP, check_count = payment_sync_status.check_count + 1,
              success = true, final_status = 'completed'
          `, [qrId]);
          return { changed: false, status: "completed" };
        }
        const movement = await walletRepository.createMovement({
          walletId: qr.walletId,
          movementType: "qr_payment",
          amount: status2.amount,
          balanceBefore: 0,
          balanceAfter: 0,
          description: status2.description || `Pago QR ${qrId}`,
          qrId,
          transactionId: qr.transactionId,
          paymentDate: status2.paymentDate || new Date().toISOString(),
          currency: status2.currency,
          senderName: status2.senderName || null,
          senderDocumentId: status2.senderDocumentId || null,
          senderAccount: status2.senderAccount || null,
          senderBankCode: status2.senderBankCode || null,
          referenceId: qr.transactionId,
          referenceType: "qr"
        });
        await query(`
          INSERT INTO payment_sync_status (qr_id, last_checked, check_count, success, final_status)
          VALUES ($1, CURRENT_TIMESTAMP, 1, true, 'completed')
          ON CONFLICT (qr_id) DO UPDATE SET
            last_checked = CURRENT_TIMESTAMP, check_count = payment_sync_status.check_count + 1,
            success = true, final_status = 'completed'
        `, [qrId]);
        eventBus.emit("qr.paid", { qrId, walletId: qr.walletId, amount: status2.amount, movementId: movement.id });
        notifService.getWalletUserIds(qr.walletId).then((userIds) => Promise.all(userIds.map((uid) => notifService.qrPaymentReceived(uid, status2.amount, qr.description || "Pago QR", qrId)))).catch((e) => logger.error("Failed to notify QR payment to wallet users", { error: e.message, qrId }));
        return { changed: true, status: "completed" };
      }
      if (status2.status === "EXPIRED" || status2.status === "CANCELLED") {
        await qrRepository.updateStatus(qrId, status2.status.toLowerCase());
        await query(`
          INSERT INTO payment_sync_status (qr_id, last_checked, check_count, success, final_status)
          VALUES ($1, CURRENT_TIMESTAMP, 1, true, $2)
          ON CONFLICT (qr_id) DO UPDATE SET
            last_checked = CURRENT_TIMESTAMP, check_count = payment_sync_status.check_count + 1,
            success = true, final_status = $2
        `, [qrId, status2.status.toLowerCase()]);
        return { changed: true, status: status2.status.toLowerCase() };
      }
      await query(`
        INSERT INTO payment_sync_status (qr_id, last_checked, check_count, success)
        VALUES ($1, CURRENT_TIMESTAMP, 1, true)
        ON CONFLICT (qr_id) DO UPDATE SET
          last_checked = CURRENT_TIMESTAMP, check_count = payment_sync_status.check_count + 1, success = true
      `, [qrId]);
      return { changed: false };
    } catch (e) {
      logger.error("Sync error for QR", { qrId, error: String(e) });
      await query(`
        INSERT INTO payment_sync_status (qr_id, last_checked, success)
        VALUES ($1, CURRENT_TIMESTAMP, false)
        ON CONFLICT (qr_id) DO UPDATE SET last_checked = CURRENT_TIMESTAMP, success = false
      `, [qrId]);
      return { changed: false };
    }
  }
};

// src/payments/sync/payment-queue.service.ts
init_logger();
var syncQueues = new Map;
var MAX_ATTEMPTS = 20;
var SWEEPER_INTERVAL = 5 * 60 * 1000;
var sweeperStartedAt = null;
var lastSweepAt = null;
var lastSweepCount = 0;
function getInterval(attempts) {
  if (attempts <= 3)
    return 30 * 1000;
  if (attempts <= 8)
    return 2 * 60 * 1000;
  if (attempts <= 12)
    return 5 * 60 * 1000;
  return 15 * 60 * 1000;
}
var paymentQueueService = {
  enqueueSync(qrId) {
    if (syncQueues.has(qrId))
      return;
    this.scheduleNext(qrId, 0);
  },
  scheduleNext(qrId, attempts) {
    const existing = syncQueues.get(qrId);
    if (existing)
      clearTimeout(existing.timer);
    const interval = getInterval(attempts);
    const timer = setTimeout(async () => {
      const { changed } = await paymentSyncService2.syncQRStatus(qrId);
      const nextAttempts = attempts + 1;
      if (!changed && nextAttempts < MAX_ATTEMPTS) {
        this.scheduleNext(qrId, nextAttempts);
      } else {
        syncQueues.delete(qrId);
      }
    }, interval);
    syncQueues.set(qrId, { timer, attempts });
  },
  async startAll() {
    try {
      const qrIds = await qrRepository.listActive();
      for (const qrId of qrIds) {
        this.enqueueSync(qrId);
      }
      logger.info(`Sync worker: ${qrIds.length} QR(s) activo(s) re-encolado(s)`);
    } catch (e) {
      logger.error("Sync worker: error re-encolando QRs activos", { error: String(e) });
    }
  },
  startSweeper() {
    sweeperStartedAt = Date.now();
    return setInterval(async () => {
      try {
        const qrIds = await qrRepository.listActive();
        let added = 0;
        for (const qrId of qrIds) {
          if (!syncQueues.has(qrId)) {
            this.enqueueSync(qrId);
            added++;
          }
        }
        lastSweepAt = Date.now();
        lastSweepCount = added;
      } catch (e) {
        logger.error("Sync sweeper error", { error: String(e) });
      }
    }, SWEEPER_INTERVAL);
  },
  stopAll() {
    for (const [qrId, { timer }] of syncQueues) {
      clearTimeout(timer);
    }
    syncQueues.clear();
  },
  getStats() {
    const now = Date.now();
    const entries = Array.from(syncQueues.entries());
    return {
      running: sweeperStartedAt !== null,
      queuedQrs: entries.length,
      maxAttempts: MAX_ATTEMPTS,
      sweeperIntervalMs: SWEEPER_INTERVAL,
      sweeperStartedAt: sweeperStartedAt ? new Date(sweeperStartedAt).toISOString() : null,
      lastSweepAt: lastSweepAt ? new Date(lastSweepAt).toISOString() : null,
      lastSweepSecondsAgo: lastSweepAt ? Math.round((now - lastSweepAt) / 1000) : null,
      lastSweepRequeued: lastSweepCount,
      queuedQrIds: entries.slice(0, 50).map(([qrId, { attempts }]) => ({ qrId, attempts }))
    };
  }
};

// src/payments/qr/qr.service.ts
init_pool();
function defaultDueDate(days = 30) {
  const d = new Date;
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}
var qrService = {
  async generate(data) {
    let targetWallet;
    if (data.walletId) {
      targetWallet = await walletRepository.getById(data.walletId);
      if (!targetWallet)
        throw new AppError2(404, "Billetera no encontrada");
    } else {
      targetWallet = await walletRepository.getBusinessAccount();
      if (!targetWallet)
        throw new AppError2(500, "Billetera empresarial no configurada");
    }
    const cc = await query(`SELECT baneco_credential_id FROM collection_config WHERE wallet_id = $1 AND is_active = true AND deleted_at IS NULL LIMIT 1`, [targetWallet.id]);
    const bcid = cc.rowCount ? cc.rows[0].baneco_credential_id : null;
    const cred = await resolveCredentials(bcid, bcid ? undefined : "prod");
    const adapter = new BanecoAdapter(cred.api_base_url, cred.encryption_key);
    const token = await adapter.getToken(cred.username, cred.password);
    const transactionId = data.transactionId ? String(data.transactionId) : `TXN${Date.now()}${Math.random().toString(36).slice(2, 8)}`.toUpperCase();
    const dueDate = data.dueDate || defaultDueDate();
    const result = await adapter.generateQr(token, transactionId, cred.account_number, data.amount, {
      description: data.description,
      dueDate,
      singleUse: data.singleUse,
      modifyAmount: data.modifyAmount,
      currency: data.currency
    });
    const qr = await qrRepository.create({
      qrId: result.qrId,
      transactionId,
      walletId: targetWallet.id,
      banecoCredentialId: bcid,
      banecoEnvironment: cred.environment,
      userId: data.userId,
      amount: data.amount,
      currency: data.currency || "BOB",
      description: data.description,
      dueDate,
      qrImage: result.qrImage,
      singleUse: data.singleUse,
      modifyAmount: data.modifyAmount
    });
    paymentQueueService.enqueueSync(result.qrId);
    eventBus.emit("qr.created", { qrId: result.qrId, walletId: targetWallet.id, amount: data.amount });
    return qr;
  },
  async list(walletId, filters) {
    return qrRepository.listByAccount(walletId, filters);
  },
  async listByUser(userId, filters) {
    return qrRepository.listByUser(userId, filters);
  },
  async getDetails(qrId) {
    return qrRepository.getByQrId(qrId);
  },
  async getPayments(qrId) {
    return qrRepository.getPayments(qrId);
  },
  async checkStatus(qrId) {
    const qr = await qrRepository.getByQrId(qrId);
    if (!qr)
      return null;
    const existing = await qrRepository.getPayments(qrId);
    let synced = false;
    if (qr.status === "active" && existing.length === 0) {
      const res = await paymentSyncService.syncQRStatus(qrId);
      synced = res.changed;
    }
    const freshQr = await qrRepository.getByQrId(qrId);
    const payments = await qrRepository.getPayments(qrId);
    return { ...freshQr, payments, synced };
  },
  async cancel(qrId) {
    const qr = await qrRepository.getByQrId(qrId);
    if (!qr)
      throw new AppError2(404, "QR no encontrado");
    if (qr.status !== "active")
      throw new AppError2(400, "El QR no está activo");
    const qrBcid = qr.baneco_credential_id;
    const cred = await resolveCredentials(qrBcid, qr.banecoEnvironment);
    try {
      const adapter = new BanecoAdapter(cred.api_base_url, cred.encryption_key);
      const token = await adapter.getToken(cred.username, cred.password);
      await adapter.cancelQr(token, qrId);
    } catch (e) {
      logger.error("Error cancelando QR en banco", { error: String(e), qrId });
    }
    await qrRepository.updateStatus(qrId, "cancelled");
    eventBus.emit("qr.cancelled", { qrId, walletId: qr.walletId });
  },
  async handleBanecoNotification(data) {
    const {
      qrId,
      transactionId,
      amount,
      paymentDate,
      paymentHour,
      currency,
      senderName,
      senderDocumentId,
      senderAccount,
      senderBankCode
    } = data;
    const qr = await qrRepository.getByQrId(qrId);
    if (!qr)
      throw new AppError2(404, "QR no encontrado");
    await qrRepository.updateStatus(qrId, "used");
    if (qr.userId) {
      try {
        const clientConfigs = await query(`
          SELECT * FROM collection_config WHERE wallet_id = $1 AND is_active = true LIMIT 1
        `, [qr.walletId]);
        if (!clientConfigs.rowCount) {
          logger.warn("No collection config for wallet, skipping", { walletId: qr.walletId, qrId });
          return;
        }
        const clientConfig = clientConfigs.rows[0];
        if (clientConfig.collection_type === "direct") {
          const rate = clientConfig.commission_rate || 0;
          const commission = amount * (rate / 100);
          const { directTransactionService: directTransactionService2 } = await Promise.resolve().then(() => (init_direct_transaction_service(), exports_direct_transaction_service));
          await directTransactionService2.create({
            userId: qr.userId,
            configId: clientConfig.id,
            qrCodeId: qr.id,
            grossAmount: amount,
            commission,
            commissionRate: rate,
            currency: currency || qr.currency,
            reference: transactionId
          });
          logger.info("Direct transaction created", { userId: qr.userId, grossAmount: amount, commission });
        } else {
          const movement2 = await walletRepository.createMovement({
            walletId: qr.walletId,
            movementType: "qr_payment",
            amount,
            balanceBefore: 0,
            balanceAfter: 0,
            description: `Pago QR ${qrId}`,
            qrId,
            transactionId,
            paymentDate: paymentDate || new Date().toISOString(),
            currency: currency || qr.currency,
            senderName,
            senderDocumentId,
            senderAccount,
            senderBankCode,
            referenceId: qr.transactionId,
            referenceType: "qr",
            status: "completed"
          });
          const userWallets = await walletRepository.listByUser(qr.userId);
          const userWallet = userWallets.find((a12) => a12.level === "bronze");
          if (!userWallet) {
            logger.warn("No wallet found for user, skipping settlement", { userId: qr.userId, qrId });
            return;
          }
          const commissionRate = clientConfig.use_default ? parseFloat(process.env.IATHINGS_CLIENT_COMMISSION_RATE || "0.01") : 0;
          const grossAmount = amount;
          const commission = grossAmount * (commissionRate / 100);
          const netAmount = grossAmount - commission;
          const settlement = await settlementRepository.create({
            fromWalletId: qr.walletId,
            configId: clientConfig.id,
            userId: qr.userId,
            grossAmount,
            commission,
            commissionRate,
            netAmount,
            currency: currency || qr.currency,
            qrCodeId: qr.id
          });
          logger.info("Settlement created", {
            settlementId: settlement.id,
            userId: qr.userId,
            netAmount,
            walletType: userWallet.type
          });
          notifService.qrPaymentReceived(qr.userId, amount, qr.description || "Pago QR", qrId, senderName).catch((e) => logger.error("Failed to send QR payment notification", { error: e.message, qrId }));
        }
      } catch (e) {
        logger.error("Error processing payment notification", { error: e.message, qrId });
      }
      return;
    }
    const movement = await walletRepository.createMovement({
      walletId: qr.walletId,
      movementType: "qr_payment",
      amount,
      balanceBefore: 0,
      balanceAfter: 0,
      description: `Pago QR ${qrId}`,
      qrId,
      transactionId,
      paymentDate: paymentDate || new Date().toISOString(),
      currency: currency || qr.currency,
      senderName,
      senderDocumentId,
      senderAccount,
      senderBankCode,
      referenceId: qr.transactionId,
      referenceType: "qr",
      status: "completed"
    });
    eventBus.emit("qr.paid", { qrId, walletId: qr.walletId, amount, movementId: movement.id });
    notifService.getWalletUserIds(qr.walletId).then((userIds) => Promise.all(userIds.map((uid) => notifService.qrPaymentReceived(uid, amount, qr.description || "Pago QR", qrId, senderName)))).catch((e) => logger.error("Failed to notify QR payment to wallet users", { error: e.message, qrId }));
  }
};

